CREATE OR REPLACE FUNCTION public.guard_active_account_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE account_status text;
BEGIN
  IF TG_TABLE_NAME = 'Membership' THEN
    IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  END IF;
  SELECT status INTO account_status FROM "User" WHERE id = NEW."userId" FOR SHARE;
  IF account_status <> 'active' THEN
    RAISE EXCEPTION 'ACCOUNT_UNAVAILABLE' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_last_company_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE company_state text;
BEGIN
  IF OLD.role = 'owner' AND OLD.status = 'active'
    AND (TG_OP = 'DELETE' OR NEW.role <> 'owner' OR NEW.status <> 'active' OR NEW."tenantId" <> OLD."tenantId") THEN
    SELECT status INTO company_state FROM "Company" WHERE id = OLD."tenantId" FOR UPDATE;
    IF company_state <> 'closed' AND NOT EXISTS (
      SELECT 1 FROM "Membership" WHERE "tenantId" = OLD."tenantId"
        AND role = 'owner' AND status = 'active' AND id <> OLD.id
    ) THEN
      RAISE EXCEPTION 'LAST_OWNER_REQUIRED' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

